-- require("myColors")


------------------
---- MONITORS ----
------------------

-- See https://wiki.hypr.land/Configuring/Basics/Monitors/
hl.monitor({
    output   = "",
    mode     = "preferred",
    position = "auto",
    scale    = "auto",
})

-- Allow the requested fractional scale at 1920x1080.
hl.config({ debug = { disable_scale_checks = true } })

-- XWayland apps (e.g. ONLYOFFICE) render pixelated/blurry under fractional
-- scaling; disabling compositor upscaling keeps them crisp.
hl.config({ xwayland = { force_zero_scaling = true } })
hl.monitor({
    output   = "eDP-1",
    mode     = "1920x1080@120",
    position = "auto",
    scale    = 1.3,
})


---------------------
---- MY PROGRAMS ----
---------------------

-- Set programs that you use
local terminal    = "kitty"
local fileManager = "nautilus"
local menu        = "hyprlauncher"


-------------------
---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/Configuring/Basics/Autostart/

hl.on("hyprland.start", function ()
    hl.exec_cmd("systemctl --user import-environment WAYLAND_DISPLAY XDG_CURRENT_DESKTOP HYPRLAND_INSTANCE_SIGNATURE")
    hl.exec_cmd("systemctl --user start hyprland-session.target")
    hl.exec_cmd("waybar")
    hl.exec_cmd("mako")
    hl.exec_cmd("systemctl --user start hypr-wallpaper.service")
end)

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
